if (!isfinite(ms_config.max_slew_t_s) || ms_config.max_slew_t_s <= 0.0 ||
    !isfinite((double)ms_config.max_rejects) ||
    ms_config.max_rejects < 1U || ms_config.max_rejects > 10U) {
    ms_state.mode = MS_FAULT;
    ms_state.rejects = 0U;
    ms_state.previous_field_t.x = 0.0;
    ms_state.previous_field_t.y = 0.0;
    ms_state.previous_field_t.z = 0.0;

    ms_output.mode = MS_FAULT;
    ms_output.rejects = 0U;
    ms_output.accepted_field_t.x = 0.0;
    ms_output.accepted_field_t.y = 0.0;
    ms_output.accepted_field_t.z = 0.0;
    ms_output.rate_t_s.x = 0.0;
    ms_output.rate_t_s.y = 0.0;
    ms_output.rate_t_s.z = 0.0;
    ms_output.rate_norm_t_s = 0.0;
    ms_output.field_energy_t2 = 0.0;
    return;
}

// 2. Handle Disabled State
if (ms_input.enable == 0) {
    ms_state.mode = MS_EMPTY;
    ms_state.rejects = 0U;
    ms_state.previous_field_t.x = 0.0;
    ms_state.previous_field_t.y = 0.0;
    ms_state.previous_field_t.z = 0.0;

    ms_output.mode = MS_EMPTY;
    ms_output.rejects = 0U;
    ms_output.accepted_field_t.x = 0.0;
    ms_output.accepted_field_t.y = 0.0;
    ms_output.accepted_field_t.z = 0.0;
    ms_output.rate_t_s.x = 0.0;
    ms_output.rate_t_s.y = 0.0;
    ms_output.rate_t_s.z = 0.0;
    ms_output.rate_norm_t_s = 0.0;
    ms_output.field_energy_t2 = 0.0;
    return;
}

// 3. Validate Input Data
const adcs_vec3_t *current_field = ms_input.field_body_t;
double dt = ms_input.dt_s;

int valid_input = 1;
if (current_field == NULL) {
    valid_input = 0;
} else if (!adcs_is_finite_vec3(current_field)) {
    valid_input = 0;
} else if (!isfinite(dt) || dt <= 0.0) {
    valid_input = 0;
} else {
    double energy = adcs_vec3_dot(current_field, current_field);
    if (energy <= FLT64_ZERO) { // Zero field is degenerate
        valid_input = 0;
    }
}

if (!valid_input) {
    // Invalid input latches FAULT, does not accept current field
    if (ms_state.mode != MS_FAULT) {
        ms_state.mode = MS_FAULT;
    }

    ms_output.mode = ms_state.mode;
    ms_output.rejects = ms_state.rejects;
    ms_output.accepted_field_t = ms_state.previous_field_t;
    ms_output.rate_t_s.x = 0.0;
    ms_output.rate_t_s.y = 0.0;
    ms_output.rate_t_s.z = 0.0;
    ms_output.rate_norm_t_s = 0.0;
    ms_output.field_energy_t2 = 0.0;
    return;
}

// 4. First Valid Field Initialization
if (ms_state.mode == MS_EMPTY) {
    ms_state.previous_field_t = *current_field;
    ms_state.mode = MS_TRACK;
    ms_state.rejects = 0U;

    ms_output.mode = MS_TRACK;
    ms_output.rejects = 0U;
    ms_output.accepted_field_t = *current_field;
    ms_output.rate_t_s.x = 0.0;
    ms_output.rate_t_s.y = 0.0;
    ms_output.rate_t_s.z = 0.0;
    ms_output.rate_norm_t_s = 0.0;
    ms_output.field_energy_t2 = adcs_vec3_dot(current_field, current_field);
    return;
}

// 5. Later Samples: Compute Rate
adcs_vec3_t delta = adcs_vec3_sub(current_field, &ms_state.previous_field_t);
adcs_vec3_t rate = adcs_vec3_scale(&delta, 1.0 / dt);
double rate_norm = adcs_vec3_norm(&rate);
double field_energy = adcs_vec3_dot(current_field, current_field);

// 6. Plausibility Check and History Update
if (rate_norm <= ms_config.max_slew_t_s) {
    // Accepted
    ms_state.previous_field_t = *current_field;
    ms_state.rejects = 0U;
    ms_state.mode = MS_TRACK;

    ms_output.mode = MS_TRACK;
    ms_output.rejects = 0U;
    ms_output.accepted_field_t = *current_field;
    ms_output.rate_t_s = rate;
    ms_output.rate_norm_t_s = rate_norm;
    ms_output.field_energy_t2 = field_energy;
} else {
    // Rejected
    ms_state.rejects++;
    if (ms_state.rejects >= ms_config.max_rejects) {
        ms_state.mode = MS_FAULT;
    } else {
        ms_state.mode = MS_REJECT;
    }
    // History preserved (previous_field_t unchanged)

    ms_output.mode = ms_state.mode;
    ms_output.rejects = ms_state.rejects;
    ms_output.accepted_field_t = ms_state.previous_field_t; // Preserve field
    ms_output.rate_t_s = rate;
    ms_output.rate_norm_t_s = rate_norm;
    ms_output.field_energy_t2 = field_energy;
}

