const adcs_vec3_t *field = ms_input.field_body_t;
double dt = ms_input.dt_s;

int input_valid = 1;
if (field == NULL) {
    input_valid = 0;
} else if (!adcs_is_finite_vec3(field)) {
    input_valid = 0;
} else {
    double norm_sq = adcs_vec3_dot(field, field);
    if (norm_sq <= FLT64_ZERO) {
