    input_valid = 0;
}

if (!input_valid) {
    ms_output.mode = MS_FAULT;
    // Do not accept current field, so history remains unchanged in ms_state
    // However, outputs are already set to defaults above.
    // Should we preserve the last valid output? 
    // The requirement says "latches FAULT". 
    // Since we initialized outputs to 0/Empty at start, this is consistent with a fresh fault or error state.
    return;
