    rate_t_s = adcs_vec3_scale(&delta, 1.0 / dt);
    rate_norm_t_s = adcs_vec3_norm(&rate_t_s);

    if (rate_norm_t_s <= ms_config.max_slew_t_s) {
        // Accepted
        ms_state.previous_field_t = *field;
        ms_state.mode = MS_TRACK;
        ms_state.rejects = 0;

        ms_output.mode = MS_TRACK;
        ms_output.rejects = 0;
        ms_output.accepted_field_t = ms_state.previous_field_t;
        ms_output.rate_t_s = rate_t_s;
        ms_output.rate_norm_t_s = rate_norm_t_s;
        ms_output.field_energy_t2 = field_energy_t2;
    } else {
        // Rejected
        ms_state.mode = MS_REJECT;
        ms_state.rejects++;

        if (ms_state.rejects >= ms_config.max_rejects) {
            ms_state.mode = MS_FAULT;
        }

        // Preserve field (don't update previous_field_t)
        ms_output.mode = ms_state.mode;
        ms_output.rejects = ms_state.rejects;
        ms_output.accepted_field_t = ms_state.previous_field_t; // Preserved
        ms_output.rate_t_s = rate_t_s;
        ms_output.rate_norm_t_s = rate_norm_t_s;
        ms_output.field_energy_t2 = field_energy_t2;
    }
}

